-- Phase 4A data migration. Reconciles the rows created by the first site_pages
-- migration with the current service-page templates. It is additive, preserves
-- ids/history, and intentionally keeps every page as a draft.
on conflict (slug) do update set
  eyebrow = excluded.eyebrow,
  title = excluded.title,
  intro = excluded.intro,
  items = excluded.items,
  status = 'draft',
  sort_order = excluded.sort_order,
  updated_at = now();
